import {escapeHtml as esc,icon} from './components.js';
const dollars=n=>Number.isFinite(n)?'$'+new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n):'공시 확인 전';
const quarter=d=>d?d.slice(0,4)+'년 '+Math.ceil(Number(d.slice(5,7))/3)+'분기':'분기 확인 전';
const fields=[['countMin','최소 보유 종목 수'],['countMax','최대 보유 종목 수'],['valueMin','최소 공개 보유액 ($)'],['valueMax','최대 공개 보유액 ($)'],['top5Min','상위 5종목 집중도 ≥ (%)'],['sectorMin','선택 섹터 비중 ≥ (%)'],['newMin','신규 편입 종목 수 ≥']];
const quicks=[['recommended','주요 운용사'],['focused','집중 투자'],['active','활발한 포지션 변화'],['technology','기술주 비중 높음'],['new','최근 신규 매수 많음']];
export function mountManagerExplorer(root){
 let destroyed=false,controller,data,version=0,p=new URLSearchParams(location.search);p.delete('mode');
 root.className='managers-page';root.innerHTML='<div class="page-heading"><div><div class="eyebrow">INSTITUTIONAL HOLDINGS</div><h1>운용사 보유 현황</h1></div><span class="manager-heading-note">미국 13F 공시</span></div><section class="surface manager-explorer"><div class="manager-search-modes"><button aria-pressed="true">운용사·인물 검색</button><a data-nav href="/managers?mode=stock">종목으로 운용사 찾기</a></div><form class="manager-explore-form"><div class="manager-search-form">'+icon('search')+'<input name="q" aria-label="운용사 한글명·영문명·인물·티커·CIK 검색" placeholder="한글·영문 운용사명, 인물, 티커 또는 CIK" maxlength="100"><button class="primary-button">검색</button></div><div class="manager-quick-filters">'+quicks.map(([key,label])=>'<button type="button" data-explore="quick" data-quick="'+key+'">'+label+'</button>').join('')+'</div><div class="manager-explore-main"><label>정렬 <select name="sort" aria-label="운용사 정렬"><option value="filed">최근 공시순</option><option value="value">공개 보유액순</option><option value="count">보유 종목 수순</option><option value="famous">대표 목록순</option><option disabled>공격적인 순 · 가격 이력 검증 필요</option><option disabled>모의 수익률순 · 계산 자료 부족</option></select></label><button type="button" data-explore="reset">초기화</button></div><details class="manager-advanced"><summary>상세 조건</summary><div class="manager-filter-grid"><label>최근 공시 분기<select name="period"><option value="">전체 분기</option></select></label><label>섹터<select name="sector"><option value="">전체 섹터</option></select></label>'+fields.map(([name,label])=>'<label>'+label+'<input type="number" name="'+name+'" min="0" '+(['top5Min','sectorMin'].includes(name)?'max="100"':'')+' step="any" placeholder="제한 없음"></label>').join('')+'</div><button class="secondary-button">조건 적용</button></details></form><div class="manager-applied" aria-live="polite"></div></section><div class="manager-explorer-status" role="status"></div><div class="manager-results manager-explore-results"></div><div class="manager-pagination"></div><details class="manager-method surface"><summary>정렬·계산 기준</summary><div></div></details>';
 const form=root.querySelector('form'),results=root.querySelector('.manager-results'),status=root.querySelector('.manager-explorer-status');
 function hydrate(){for(const control of form.elements)if(control.name)control.value=p.get(control.name)|| (control.name==='sort'?'filed':'');for(const b of root.querySelectorAll('[data-quick]'))b.setAttribute('aria-pressed',String(p.get('quick')===b.dataset.quick));}
 function sync(){const query=p.toString();history.replaceState(null,'','/managers'+(query?'?'+query:''));hydrate();}
 function cards(items){return items.map(m=>'<a class="surface manager-explore-card" data-nav href="/managers/'+m.cik+'"><div class="manager-explore-card-head"><span class="manager-initial">'+esc(m.name.slice(0,1))+'</span><div><h2>'+esc(m.name)+'</h2><p>'+esc(m.relatedPeople?.length?'관련 인물: '+m.relatedPeople.join(' · '):'관련 인물 확인 전')+'</p><small>CIK '+esc(m.cik.padStart(10,'0'))+'</small></div>'+(m.searchMatch&&!m.searchMatch.label.startsWith('관련 인물: ')?'<small class="manager-search-match">'+esc(m.searchMatch.label)+'</small>':'')+(m.recommended?'<b class="manager-recommend">대표 목록</b>':'')+'</div><div class="manager-card-quarter">'+quarter(m.period)+' · '+(m.filedAt?esc(m.filedAt)+' 제출':'제출일 확인 전')+'</div><dl><div><dt>공개 보유액</dt><dd>'+dollars(m.totalValue)+'</dd></div><div><dt>보유 종목</dt><dd>'+(Number.isFinite(m.holdingCount)?m.holdingCount.toLocaleString()+'개':'공시 확인 전')+'</dd></div><div><dt>상위 5종목 집중도</dt><dd>'+(Number.isFinite(m.concentration)?m.concentration.toFixed(1)+'%':'상세 공시 필요')+'</dd></div><div><dt>주요 섹터</dt><dd>'+esc(m.mainSector||'분류 확인 전')+'</dd></div></dl><div class="manager-top-holdings">'+(m.top3?.length?m.top3.map(r=>'<span>'+esc(r.ticker||r.name)+'</span>').join(''):'<span>상위 종목 · 상세 공시 확인 전</span>')+'</div><small class="manager-card-updated">확인 '+new Date(m.receivedAt).toLocaleDateString('ko-KR')+(m.missingReason?' · '+esc(m.missingReason):'')+'</small></a>').join('');}
 async function load(){controller?.abort();controller=new AbortController();const n=++version;status.textContent='조건에 맞는 운용사 불러오는 중';try{const r=await fetch('/api/managers/explore?'+p,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(45000)])}),d=await r.json();if(destroyed||n!==version)return;if(!r.ok||d.status==='error')throw new Error(d.message||'운용사를 불러오지 못했습니다.');data=d;
  for(const [key,label,values] of [['period','전체 분기',d.periods],['sector','전체 섹터',d.sectors]])form.elements[key].innerHTML='<option value="">'+label+'</option>'+[...new Set([...(values||[]),...(p.get(key)?[p.get(key)]:[])])].map(v=>'<option value="'+esc(v)+'">'+esc(key==='period'?quarter(v):v)+'</option>').join('');hydrate();
  results.innerHTML=d.items.length?cards(d.items):'<div class="data-state"><strong>조건에 맞는 운용사가 없습니다</strong><p>상세 공시가 없는 운용사는 해당 수치 조건에서 제외됩니다.</p></div>';
  status.textContent=(p.get('q')?'검색 일치도 우선 · ':'')+(p.get('sort')==='famous'?'관리자 대표 운용사 순서 기준 · ':'')+d.total+'개 결과 · 저장된 운용사 '+d.coverage.directory+'곳 중 상세 공시 '+d.coverage.verified+'곳 기준'+(d.warning?' · '+d.warning:'');
  root.querySelector('.manager-pagination').innerHTML='<button data-explore="previous" '+(Number(p.get('page')||1)<=1?'disabled':'')+'>이전</button><span>'+d.page+' 페이지</span><button data-explore="next" '+(!d.nextPage?'disabled':'')+'>다음</button>';
  const labels={q:'검색',period:'분기',sector:'섹터',quick:'빠른 조건',...Object.fromEntries(fields)};root.querySelector('.manager-applied').innerHTML=[...p].filter(([k,v])=>v&&labels[k]).map(([k,v])=>'<span>'+esc(labels[k])+': '+esc(k==='quick'?quicks.find(x=>x[0]===v)?.[1]||v:v)+'</span>').join('')||'<span>전체 조건</span>';
  root.querySelector('.manager-method>div').innerHTML='<p>필터와 정렬은 현재 사이트에 저장·확인된 운용사를 대상으로 합니다. 이름·인물명 검색은 Finviz 검색 결과를 추가합니다. 공개 보유액은 13F 공시상 평가액이며 전체 AUM이 아닙니다.</p><p>집중 투자: 상위 5종목 ≥ 50% · 활발한 변화: 수량 변화 기준 ≥ 30% · 기술주: Technology ≥ 40% · 최근 신규: 주식 신규 편입 ≥ 5개. 주식 수 비교에는 분할 등도 포함될 수 있습니다.</p><p>대표 목록순은 관리자 대표 목록 순서를 사용합니다. 미지정 운용사는 최근 공시순으로 이어집니다. 관련 인물 표시는 현재 운용 책임자를 뜻하지 않습니다.</p>'+Object.entries(d.availability).map(([key,a])=>'<p'+(a.formula?' tabindex="0" title="'+esc(a.formula)+'"':'')+'><b>'+({popularity:'유명도',aggression:'13F 공개 포지션 기준 공격성',returns:'13F 기반 모의 수익률'}[key])+':</b> '+esc(a.reason)+(a.formula?'<br>'+esc(a.formula):'')+'</p>').join('');
 }catch(e){if(!destroyed&&n===version&&e.name!=='AbortError'){status.textContent='운용사를 불러오지 못했습니다. 검색을 다시 눌러 주세요.';results.innerHTML='';}}}
 function apply(){const next=new URLSearchParams(new FormData(form));for(const [k,v]of [...next])if(!v||k==='sort'&&v==='filed')next.delete(k);if(p.get('quick'))next.set('quick',p.get('quick'));p=next;sync();load();}
 const submit=e=>{e.preventDefault();apply();},change=e=>{if(e.target.name==='sort')apply();},click=e=>{const b=e.target.closest('[data-explore]');if(!b)return;const a=b.dataset.explore;if(a==='reset'){p=new URLSearchParams();sync();load();}if(a==='quick'){const q=b.dataset.quick;p.get('quick')===q?p.delete('quick'):p.set('quick',q);p.delete('page');sync();load();}if(a==='previous'||a==='next'){p.set('page',String(a==='next'?data.nextPage:Math.max(1,Number(p.get('page')||1)-1)));sync();load();}};
 form.addEventListener('submit',submit);root.addEventListener('change',change);root.addEventListener('click',click);hydrate();load();
 return {destroy(){destroyed=true;controller?.abort();form.removeEventListener('submit',submit);root.removeEventListener('change',change);root.removeEventListener('click',click);}};
}
